type Post = {
  id: number
  title: string
  body?: string
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5'
  )
  if (!res.ok) {
    throw new Error('Failed to fetch posts')
  }
